        const idxLocation = findColIndex(headers, MAP_ELEMENT_COL.location);
        const idxDesc = findColIndex(headers, MAP_ELEMENT_COL.description);
        const idxStatus = findColIndex(headers, MAP_ELEMENT_COL.status);
